/** @param {JsonRecord} execution */
function assertExecution(execution) {
  if (
    typeof execution !== "object" ||
    execution === null ||
    execution.kind !== EXECUTION_KIND ||
    execution.command !== "claude" ||
    !Array.isArray(execution.arguments) ||
    !execution.arguments.every((argument) => typeof argument === "string")
  ) {
    refuse("intent-invalid", { field: "execution" });
  }
  const forbidden = execution.arguments.find((argument) => FORBIDDEN_ARGUMENTS.includes(argument));
  if (forbidden !== undefined)
    refuse("intent-invalid", { field: "arguments", argument: forbidden });
  const desktop = execution.desktop;
  if (desktop !== undefined && (typeof desktop !== "object" || desktop === null))
    refuse("intent-invalid", { field: "desktop" });
  if (desktop?.title !== undefined && typeof desktop.title !== "string")
    refuse("intent-invalid", { field: "desktop.title" });
  if (desktop?.cwd !== undefined && typeof desktop.cwd !== "string")
    refuse("intent-invalid", { field: "desktop.cwd" });
}

// 只解析 <workspace root> 占位符（--add-dir 的工作区根与账本）；其余 <…> 占位符一律拒绝。
/** @param {readonly string[]} executionArguments */
function resolveArguments(executionArguments) {
  const resolved = executionArguments.map((argument) =>
    argument.startsWith(WORKSPACE_ROOT_PLACEHOLDER)
      ? ROOT + argument.slice(WORKSPACE_ROOT_PLACEHOLDER.length)
      : argument,
  );
  if (resolved.some((argument) => /^<[^>]*>$/u.test(argument))) refuse("placeholder-unresolved");
  return resolved;
}

// 意图的 worktree 段（登记合同的 worktreeIntent）：basePolicy local-head 与建议名；pod 窗口的检出由助手准备，不传 --worktree。
/** @param {JsonRecord} launchIntent */
function requestedWorktree(launchIntent) {
  const worktree = launchIntent.worktree;
  if (worktree === null || worktree === undefined) return null;
  if (
    typeof worktree !== "object" ||
    worktree.basePolicy !== "local-head" ||
    typeof worktree.suggestedName !== "string" ||
    !WORKTREE_NAME_PATTERN.test(worktree.suggestedName)
  ) {
    refuse("intent-invalid", { field: "worktree" });
  }
  return Object.freeze({ suggestedName: worktree.suggestedName });
}

// A8（§13.167）：hook 记录的会话 cwd 必须就是准备好的检出（按 realpath 比对）。不是时窗口在别的检出上工作、
// 基线会悄悄漂移，所以拒绝；observedCwd 相对仓库根给出，仓库之外只说 outside-repository，不带绝对路径。
/**
 * @param {Readonly<PreparedWorktree>} prepared
 * @param {string} cwd
 */
function assertPreparedCheckoutCwd(prepared, cwd) {
  const observed = realpathOrNull(cwd);
  if (observed !== null && observed === realpathOrNull(prepared.checkout)) return;
  let observedCwd = "unavailable";
  if (observed !== null) {
    const relative = path.relative(prepared.root, observed);
    if (relative.length === 0) observedCwd = ".";
    else if (relative.startsWith("..")) observedCwd = "outside-repository";
    else observedCwd = relative;
  }
  refuse("worktree-cwd-mismatch", {
    branch: prepared.branch,
    observedCwd,
    hint: "the session did not start in the prepared checkout; archive that desktop session, then launch again",
  });
}

/**
 * @param {{ readonly checkout: string }} prepared
 * @returns {Placement}
 */
function checkoutPlacement(prepared) {
  const relative = path.relative(ROOT, prepared.checkout);
  return Object.freeze({
    absolute: prepared.checkout,
    relative: relative.length === 0 ? "." : relative,
  });
}

/** @param {string} sessionId */
function desktopLocator(sessionId) {
  return Object.freeze({ sessionId: DESKTOP_SESSION_PREFIX + sessionId });
}

/**
 * @param {string} sessionId
 * @param {string} launchIntentDigest
 * @param {ReturnType<typeof observeWorktree>} worktree
 */
function creationObservation(sessionId, launchIntentDigest, worktree) {
  return Object.freeze({
    handle: { kind: HANDLE_KIND, value: sessionId },
    launchIntentDigest,
    observedAt: new Date().toISOString(),
    desktop: desktopLocator(sessionId),
    ...(worktree === null ? {} : { worktree }),
  });
}

// claude agents --json 的行（L17：interactive 行带 pid/cwd/kind/startedAt/sessionId/name/status，
// background 行带 id/cwd/kind/startedAt/sessionId/name/state）。输出是 JSON 数组；容忍包在对象里的数组。
/**
 * @param {boolean} all
 * @returns {AgentListing}
 */
function listAgents(all) {
  const result = run(claudeBinary(), ["agents", "--json", ...(all ? ["--all"] : [])]);
  if (!result.ok)
    return Object.freeze({
      available: false,
      rows: [],
      detail: boundedDetail(result.stderr.length > 0 ? result.stderr : result.stdout),
    });
  let parsed;
  try {
    parsed = JSON.parse(result.stdout);
  } catch {
    refuse("agents-json-invalid");
  }
  const rows = Array.isArray(parsed)
    ? parsed
    : parsed !== null && typeof parsed === "object"
      ? Object.values(parsed).find((value) => Array.isArray(value))
      : undefined;
  if (!Array.isArray(rows)) refuse("agents-json-invalid");
  return Object.freeze({
    available: true,
    rows: rows.filter((row) => row !== null && typeof row === "object"),
    detail: undefined,
  });
}

/**
 * @param {string} windowId
 * @returns {JsonRecord | null}
 */
function readLocator(windowId) {
  const record = readBoundedJson(
    path.join(ROOT, ...LOCATORS.split("/"), `${windowId}.json`),
    MAX_RECORD_BYTES,
  );
  if (
    record === null ||
    record.kind !== "WakeflowWindowLocator" ||
    record.hostId !== HOST_ID ||
    record.windowId !== windowId ||
    typeof record.locatorId !== "string" ||
    typeof record.bindingId !== "string" ||
    typeof record.programId !== "string"
  ) {
    return null;
  }
  return record;
}

/** @param {JsonRecord} locator */
function locatorSessionId(locator) {
  const value = locator.desktop?.sessionId;
  if (typeof value !== "string" || !value.startsWith(DESKTOP_SESSION_PREFIX)) return null;
  const sessionId = value.slice(DESKTOP_SESSION_PREFIX.length);
  return UUID_PATTERN.test(sessionId) ? sessionId : null;
}

// 定位器指向的桌面会话还在侧栏里（agents 的 interactive 行）就不再开第二个（tmux 助手 locator-live 的同一守卫）。
/**
 * @param {string} windowId
 * @param {{ force: boolean }} options
 */
function assertLocatorNotLive(windowId, options) {
  const locator = readLocator(windowId);
  if (locator === null || options.force) return;
  const sessionId = locatorSessionId(locator);
  if (sessionId === null) return;
  const listed = listAgents(false);
  if (!listed.available) return;
  const live = listed.rows.find((row) => row.kind === "interactive" && row.sessionId === sessionId);
  if (live !== undefined) {
    refuse("locator-live", {
      desktop: desktopLocator(sessionId),
      status: live.status === "busy" ? "busy" : "idle",
      hint: "the window's desktop session is still open: send to it or archive it first; --force launches a second session anyway",
    });
  }
}

function assertDesktopReady() {
  if (scriptBinary() === null) {
    refuse("script-unavailable", {
      hint: "the pseudo-terminal wrapper script(1) is not on PATH; claude --desktop refuses redirected output without it",
    });
  }
  const desktop = desktopAppState();
  if (!desktop.appRunning) {
    refuse("desktop-unavailable", {
      stage: "preflight",
      appRunning: false,
      processTable: desktop.processTable,
      hint: "start the Claude desktop app and sign in, then launch again",
    });
  }
}

// 自检（设计 §3.2 的 prompt-position）：prompt 必须是 --bg 之后的第一个位置参数，且只出现这一次；跟在变长的
// --add-dir / --allowedTools 之后的 prompt 会被当成目录或工具名，会话空闲起步（L17 E1 第一次失败）。
/**
 * @param {readonly string[]} argv
 * @param {string} prompt
 */
function assertPromptPosition(argv, prompt) {
  if (argv[0] !== "--bg" || argv[1] !== prompt || argv.lastIndexOf(prompt) !== 1)
    refuse("prompt-position");
}

/** @param {string} text */
function stripSgr(text) {
  return text.replace(SGR_PATTERN, "");
}

// --bg 的输出："backgrounded · <短 id> · <名字>"；也接受直接打印完整 uuid 的形态。
/**
 * @param {string} output
 * @returns {string}
 */
function parseBackgroundId(output) {
  const text = stripSgr(output);
  const line = text.split(/\r?\n/u).find((entry) => BACKGROUNDED_PATTERN.test(entry)) ?? "";
  const words = line.split(/[\s·•|:]+/u).filter((word) => word.length > 0);
  const uuid = words.find((word) => UUID_PATTERN.test(word));
  if (uuid !== undefined) return uuid;
  const index = words.findIndex((word) => BACKGROUNDED_PATTERN.test(word));
  const candidate = words[index + 1];
  if (index !== -1 && candidate !== undefined && SHORT_ID_PATTERN.test(candidate)) return candidate;
  refuse("launch-id-unparsed", { detail: boundedDetail(text) });
}

// 信任记录按 Git 仓库的顶层目录认（探针 E9；现场 L23）：工作区根的记录覆盖根仓库里的普通子目录（Design、Test 面），
// 嵌套的产品仓库与 pod 检出各认自己的顶层。目录不在任何仓库里时就是它自己。相对工作区根给出，不带绝对路径。
/**
 * @param {Placement} cwd
 * @returns {Placement}
 */
function trustRootOf(cwd) {
  const toplevel = git(cwd.absolute, ["rev-parse", "--show-toplevel"]);
  const resolved =
    toplevel.ok && toplevel.stdout.trim().length > 0
      ? realpathOrNull(toplevel.stdout.trim())
      : null;
  if (resolved === null) return cwd;
  const relative = path.relative(realpathOrNull(ROOT) ?? ROOT, resolved);
  return Object.freeze({ absolute: resolved, relative: relative.length === 0 ? "." : relative });
}

/**
 * @param {Placement} cwd
 * @param {readonly string[]} argv
 */
function startBackgroundSession(cwd, argv) {
  const started = run(claudeBinary(), argv, { cwd: cwd.absolute });
  const output = `${started.stdout}\n${started.stderr}`;
  if (!started.ok) {
    if (NOT_TRUSTED_PATTERN.test(output)) {
      refuse("not-trusted", {
        cwd: cwd.relative,
        trustRoot: trustRootOf(cwd).relative,
        hint: "Claude Code has no trust record for trustRoot, the repository root this folder belongs to: go on launching the other windows, then name every distinct trustRoot to the user in one question and say what trusting it means; with their agreement run trust --window <windowId> --user-agreed once per trustRoot and launch the refused windows again, otherwise they open that folder in the Claude desktop app or run claude in a terminal there and accept the trust dialog",
      });
    }
    refuse("launch-start-failed", {
      status: started.status,
      detail: boundedDetail(started.stderr.length > 0 ? started.stderr : started.stdout),
    });
  }
  return parseBackgroundId(output);
}

/**
 * @param {readonly JsonRecord[]} rows
 * @param {string} id
 */
function backgroundRow(rows, id) {
  return rows.find((row) => row.id === id || row.sessionId === id);
}

/** @param {string} shortId */
function stopBackgroundSession(shortId) {
  return run(claudeBinary(), ["stop", shortId]).ok;
}

// 首回合：轮询 claude agents --json --all 直到该行 state 为 done。行要先出现（--bg 刚返回时清单可能还没有它），
// 出现后解析出完整 uuid；failed / stopped 即失败；超时则尽力 stop 掉后台会话再拒绝，不留一个还在跑的后台作业。
/**
 * @param {string} id
 * @param {number} seconds
 */
// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: moved verbatim from the inline script (1.3.0 batch 1, no behavior change); splitting it is tracked under open-items L2
function awaitFirstTurn(id, seconds) {
  const deadline = Date.now() + seconds * 1000;
  let seen = null;
  let state = "absent";
  for (;;) {
    const listed = listAgents(true);
    if (!listed.available) refuse("agents-unavailable", { detail: listed.detail });
    const row = backgroundRow(listed.rows, id);
    if (row !== undefined) {
      const sessionId =
        typeof row.sessionId === "string" && UUID_PATTERN.test(row.sessionId)
          ? row.sessionId
          : UUID_PATTERN.test(id)
            ? id
            : null;
      if (sessionId === null) refuse("launch-session-unlisted", { id, field: "sessionId" });
      seen = Object.freeze({ shortId: typeof row.id === "string" ? row.id : id, sessionId });
      state = typeof row.state === "string" ? row.state : "unknown";
      if (FIRST_TURN_DONE_STATES.includes(state)) return Object.freeze({ ...seen, state });
      if (FIRST_TURN_FAILED_STATES.includes(state)) {
        refuse("launch-first-turn-failed", {
          state,
          handle: { kind: HANDLE_KIND, value: sessionId },
          background: { id: seen.shortId },
        });
      }
    }
    const remaining = deadline - Date.now();
    if (remaining <= 0) {
      if (seen === null) refuse("launch-session-unlisted", { id, waitedSeconds: seconds });
      const stopped = stopBackgroundSession(seen.shortId);
      refuse("launch-first-turn-timeout", {
        state,
        waitedSeconds: seconds,
        handle: { kind: HANDLE_KIND, value: seen.sessionId },
        background: { id: seen.shortId, stopped },
        hint: "the first turn did not finish in time; the background session was stopped, launch again (or raise --wait)",
      });
    }
    sleep(Math.min(AGENTS_POLL_MS, remaining));
  }
}

// 第三步：伪终端里 claude --desktop --resume <uuid>，在执行根运行（--desktop 在当前目录打开桌面 app）。
/**
 * @param {string} sessionId
 * @param {Placement} cwd
 */
function resumeIntoDesktop(sessionId, cwd) {
  const script = scriptBinary();
  if (script === null) refuse("script-unavailable");
  const result = run(
    script,
    ["-q", "/dev/null", claudeBinary(), "--desktop", "--resume", sessionId],
    { cwd: cwd.absolute, stdin: "ignore" },
  );
  const output = stripSgr(`${result.stdout}\n${result.stderr}`);
  const opened = result.ok && OPENING_SESSION_PATTERN.test(output);
  if (opened) return;
  const extra = {
    status: result.status,
    detail: boundedDetail(result.stderr.length > 0 ? result.stderr : result.stdout),
    handle: { kind: HANDLE_KIND, value: sessionId },
  };
  if (DESKTOP_UNAVAILABLE_PATTERN.test(output)) {
    refuse("desktop-unavailable", {
      stage: "resume",
      ...extra,
      hint: "the desktop app is not running or not signed in; the stopped background session keeps the conversation, launch again once the app is up",
    });
  }
  refuse("desktop-resume-refused", {
    ...extra,
    hint: "claude --desktop --resume did not report Opening session; the session may still be running or may never have conversed",
  });
}

function commandPreflight() {
  const binary = claudeBinary();
  const desktop = desktopAppState();
  const sessionId = process.env.CLAUDE_CODE_SESSION_ID;
  const sessionIdVisible = typeof sessionId === "string" && UUID_PATTERN.test(sessionId);
  return {
    ok: true,
    command: "preflight",
    // A5（§13.167）：node 的路径与版本对 contracts 声明的引擎范围核对；claude 的路径说明安装形态。
    node: Object.freeze({
      available: true,
      version: cleanLabel(process.version, "unknown", MAX_VERSION),
      path: process.execPath,
      engines: NODE_ENGINES,
      supported: nodeVersionSupported(process.versions.node),
    }),
    claude: Object.freeze({
      ...versionOf(binary, ["--version"]),
      install: claudeInstallForm(binary),
    }),
    script: Object.freeze({ available: scriptBinary() !== null }),
    desktop: Object.freeze({ appRunning: desktop.appRunning, processTable: desktop.processTable }),
    sessionIdVisible,
    // 本会话自己的 session-start 记录存在与否：引导会话（工作区建立之前启动）为 false，只能引导（§13.188）。
    sessionProven: sessionIdVisible ? sessionStartRecord(sessionId) !== null : null,
  };
}

/** @param {Readonly<DesktopHelperOptions>} options */
// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: moved verbatim from the inline script (1.3.0 batch 1, no behavior change); splitting it is tracked under open-items L2
function commandLaunch(options) {
  const { windowId, launchIntent } = unwrapIntent(readStdinJson(), options);
  const execution = launchIntent.execution;
  assertExecution(execution);
  const desktop = execution.desktop ?? {};
  const title = cleanLabel(desktop.title ?? launchIntent.displayTitle, "window");
  const resolvedArguments = resolveArguments(execution.arguments);
  const worktreeIntent = requestedWorktree(launchIntent);
  // 意图的落点在碰任何宿主命令之前核对；pod 窗口的落点是仓库主检出，真正的 cwd 是随后准备的检出。
  const repositoryRoot = resolvePlacement(launchIntent.root?.configuredPlacement);
  const placement =
    worktreeIntent === null
      ? resolvePlacement(desktop.cwd ?? launchIntent.root?.configuredPlacement)
      : repositoryRoot;
  const prompt = startupPrompt(windowId, launchIntent.role, title);
  const argv = [
    "--bg",
    prompt,
    "--name",
    title,
    ...resolvedArguments,
    "--allowedTools",
    ...sessionPermissionRules(launchIntent.role),
  ];
  assertPromptPosition(argv, prompt);
  assertLocatorNotLive(windowId, options);
  assertDesktopReady();
  const prepared =
    worktreeIntent === null
      ? null
      : prepareWorktree(repositoryRoot.absolute, worktreeIntent.suggestedName);
  const cwd = prepared === null ? placement : checkoutPlacement(prepared);
  // §13.130：检出准备好之后的失败仍带 worktreePrepared 与分支，Controller 才知道留下了一条检出。
  try {
    const id = startBackgroundSession(cwd, argv);
    const session = awaitFirstTurn(id, options.wait);
    const stopped = stopBackgroundSession(session.shortId);
    const before = new Set(sessionStartNames(session.sessionId));
    resumeIntoDesktop(session.sessionId, cwd);
    const hook = waitForNewSessionStart(session.sessionId, before, options.waitSessionStart);
    if (hook.status === "pending") {
      refuse("desktop-session-start-missing", {
        handle: { kind: HANDLE_KIND, value: session.sessionId },
        desktop: desktopLocator(session.sessionId),
        waitedSeconds: options.waitSessionStart,
        hint: "the desktop reported Opening session but no new SessionStart record arrived; check the sidebar and the hook channel, then launch again",
      });
    }
    if (prepared !== null && typeof hook.record.cwd === "string")
      assertPreparedCheckoutCwd(prepared, hook.record.cwd);
    const worktree =
      prepared !== null && typeof hook.record.cwd === "string"
        ? observeWorktree(hook.record.cwd)
        : null;
    return {
      ok: true,
      command: "launch",
      windowId,
      observation: creationObservation(session.sessionId, launchIntent.intentDigest, worktree),
      created: "launched",
      hook: { sessionStart: "observed" },
      window: { name: title, cwd: cwd.relative },
      background: { id: session.shortId, firstTurn: session.state, stopped },
      ...(prepared !== null && worktree === null ? { worktreeObservation: "pending" } : {}),
      worktreePrepared: prepared === null ? "not-requested" : prepared.prepared,
      ...(prepared === null
        ? {}
        : { worktreeBranch: prepared.branch, worktreeExclude: prepared.exclude }),
    };
  } catch (error) {
    if (prepared === null) throw error;
    const failure =
      error instanceof HelperFailure
        ? error
        : new HelperFailure("unexpected", unexpectedDetail(error));
    throw new HelperFailure(failure.reason, {
      ...failure.extra,
      worktreePrepared: prepared.prepared,
      worktreeBranch: prepared.branch,
    });
  }
}

// 裸 claude --desktop：桌面 app 切到 cwd 的新会话页并写下该目录的信任记录，不启动进程（L17 1.1、L18）。
/** @param {Placement} cwd */
function openFolderInDesktop(cwd) {
  const script = scriptBinary();
  if (script === null) refuse("script-unavailable");
  const result = run(script, ["-q", "/dev/null", claudeBinary(), "--desktop"], {
    cwd: cwd.absolute,
    stdin: "ignore",
  });
  const output = stripSgr(`${result.stdout}\n${result.stderr}`);
  if (result.ok && OPENING_FOLDER_PATTERN.test(output)) return;
  const extra = { cwd: cwd.relative, status: result.status };
  if (DESKTOP_UNAVAILABLE_PATTERN.test(output)) {
    refuse("desktop-unavailable", {
      stage: "trust",
      ...extra,
      hint: "the desktop app is not running or not signed in; ask the user to start it and sign in, then run trust again",
    });
  }
  refuse("trust-open-failed", {
    ...extra,
    hint: "claude --desktop did not report opening the folder; ask the user to open it in the Claude desktop app and accept the trust dialog",
  });
}

// trust（Q13，ADR-0025 D11）：只在用户对被拒目录的清单表示同意之后调用；信任一个目录是用户的决定。
/** @param {Readonly<DesktopHelperOptions>} options */
function commandTrust(options) {
  const { windowId, launchIntent } = unwrapIntent(readStdinJson(), options);
  if (!options.userAgreed) {
    refuse("consent-required", {
      windowId,
      hint: "trusting a folder is the user's decision: name the folders launch refused as not-trusted, say that Claude Code will then load each folder's own settings and hooks, and pass --user-agreed only after the user agrees to that list",
    });
  }
  const execution = launchIntent.execution;
  assertExecution(execution);
  const worktreeIntent = requestedWorktree(launchIntent);
  const repositoryRoot = resolvePlacement(launchIntent.root?.configuredPlacement);
  let cwd;
  if (worktreeIntent === null) {
    cwd = resolvePlacement(execution.desktop?.cwd ?? launchIntent.root?.configuredPlacement);
  } else {
    // pod 窗口的落点是 launch 准备的检出；信任从不创建检出。
    const checkout = path.join(
      repositoryRoot.absolute,
      ".claude",
      "worktrees",
      worktreeIntent.suggestedName,
    );
    if (!existsSync(checkout)) {
      refuse("checkout-missing", {
        windowId,
        hint: "launch prepares the pod checkout; launch this window first and trust it only when launch reports not-trusted",
      });
    }
    cwd = checkoutPlacement({ checkout });
  }
  assertDesktopReady();
  // 打开的是该窗口所属仓库的顶层：一条工作区根的记录就覆盖 Controller、Design 与 Test 三个窗口。
  const target = trustRootOf(cwd);
  openFolderInDesktop(target);
  if (options.settle > 0) sleep(options.settle * 1000);
  return {
    ok: true,
    command: "trust",
    windowId,
    cwd: cwd.relative,
    trustRoot: target.relative,
    opened: true,
  };
}

// 存活观察：interactive 行就是桌面 Code 标签里的会话（tmux 里的 CLI 窗口不在列，L17）。
function sessionsObservation() {
  const listed = listAgents(false);
  if (!listed.available)
    return Object.freeze({ observation: { kind: "unobserved" }, truncated: false, total: 0 });
  const rows = listed.rows.filter(
    (row) =>
      row.kind === "interactive" &&
      typeof row.sessionId === "string" &&
      UUID_PATTERN.test(row.sessionId),
  );
  const sessions = rows.slice(0, MAX_SESSIONS).map((row) => ({
    sessionId: row.sessionId,
    status: row.status === "busy" ? "busy" : "idle",
    cwd: typeof row.cwd === "string" ? row.cwd : null,
    name: cleanLabel(row.name, null, MAX_LABEL),
    pid: Number.isInteger(row.pid) ? row.pid : null,
  }));
  return Object.freeze({
    observation: { kind: "desktop-sessions", sessions },
    truncated: rows.length > MAX_SESSIONS,
    total: rows.length,
  });
}

function commandSessions() {
  return { ok: true, command: "sessions", ...sessionsObservation() };
}

// 落地证据是目标会话的 user-prompt-submit hook 记录，promptDigest 等于许可的摘要（L17 E2：桌面 send_message 与
// 跨会话 SendMessage 到 hook 的 prompt 都是原文）。只查已存在的记录，不推断，也不发送。
/** @param {Readonly<DesktopHelperOptions>} options */
// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: moved verbatim from the inline script (1.3.0 batch 1, no behavior change); splitting it is tracked under open-items L2
function commandLanding(options) {
  if (options.window === null) refuse("window-required");
  if (options.promptDigest === null && options.promptRef === null) refuse("prompt-digest-required");
  // 带 --prompt-ref 时从许可文件读出摘要与许可标识（ADR-0027）：标识让"文本被宿主改动"的落地也能认出；
  // 只给 --prompt-digest 是旧用法，那时只按摘要查。两者都给必须一致。
  const prompt = options.promptRef === null ? null : readPermitPrompt(options.promptRef);
  // 上面的守卫保证两者至少给了一个：没有许可文件时摘要一定是命令行给的那个。
  const promptDigest = /** @type {string} */ (
    prompt === null ? options.promptDigest : promptDigestOf(prompt)
  );
  if (options.promptDigest !== null && options.promptDigest !== promptDigest)
    refuse("prompt-digest-mismatch");
  const permitIds = prompt === null ? [] : promptPermitIdsOf(prompt);
  const binding = readBoundedJson(
    path.join(ROOT, ...BINDINGS.split("/"), `${options.window}.json`),
    MAX_RECORD_BYTES,
  );
  const sessionId = binding?.handle?.kind === HANDLE_KIND ? binding.handle.value : null;
  if (typeof sessionId !== "string") refuse("binding-missing", { windowId: options.window });
  const deadline = Date.now() + options.waitLanding * 1000;
  for (;;) {
    const landed = landingRecord(sessionId, promptDigest, permitIds);
    if (landed !== null) {
      return {
        ok: true,
        command: "landing",
        windowId: options.window,
        landed: true,
        match: landed.match,
        recordId: typeof landed.record.recordId === "string" ? landed.record.recordId : null,
        recordedAt: typeof landed.record.recordedAt === "string" ? landed.record.recordedAt : null,
      };
    }
    if (Date.now() >= deadline) {
      // 没有这个摘要的记录时，报出该会话最近一条别的 prompt 记录（现场 L22）：发送把文本改动了（经工具调用参数
      // 转发时反斜杠转义被解码、重排了空白）与“什么都没到”是两回事——前者不能再发一遍，只能凭这条记录裁决。
      const other = latestHookRecord("user-prompt-submit", sessionId);
      return {
        ok: true,
        command: "landing",
        windowId: options.window,
        landed: false,
        promptDigest,
        ...(other === null
          ? {}
          : {
              latestPrompt: {
                recordId: typeof other.recordId === "string" ? other.recordId : null,
                recordedAt: typeof other.recordedAt === "string" ? other.recordedAt : null,
                promptDigest: typeof other.promptDigest === "string" ? other.promptDigest : null,
              },
            }),
      };
    }
    sleep(HOOK_POLL_MS);
  }
}

function main() {
  /** @type {ReturnType<typeof parseArguments> | undefined} */
  let parsed;
  try {
    parsed = parseArguments(process.argv.slice(2));
    readConfig();
    const options = parsed.options;
    let result;
    switch (parsed.command) {
      case "preflight":
        result = commandPreflight();
        break;
      case "launch":
        result = commandLaunch(options);
        break;
      case "trust":
        result = commandTrust(options);
        break;
      case "sessions":
        result = commandSessions();
        break;
      case "landing":
        result = commandLanding(options);
        break;
      default:
        refuse("command-unknown");
    }
    emit(result, result.ok ? 0 : 1);
  } catch (error) {
    if (error instanceof HelperFailure) {
      emit(
        { ok: false, command: parsed?.command ?? null, reason: error.reason, ...error.extra },
        1,
      );
      return;
    }
    emit(
      {
        ok: false,
        command: parsed?.command ?? null,
        reason: "unexpected",
        ...unexpectedDetail(error),
      },
      2,
    );
  }
}

main();
